chars=['\0']+sorted(rows,key=ord); glyf=b''; offsets=[]; metrics=b''
for ch in chars:
 offsets.append(len(glyf)); grid=rows.get(ch,rows['?']).split('/'); pts=[]; ends=[]
 for y,row in enumerate(grid):
  for x,v in enumerate(row):
   if v=='1':
    pts.extend([(x*128,(7-y)*128),((x+1)*128,(7-y)*128),((x+1)*128,(6-y)*128),(x*128,(6-y)*128)]);ends.append(len(pts)-1)
 if pts:
  g=P('hhhhh',len(ends),0,0,max(x for x,y in pts),896)+P('H'*len(ends),*ends)+P('H',0)+bytes([1]*len(pts))
